// Acceptance C: a library part on the input shaft gets a printed mate with a
// freely chosen tooth count; mates of arbitrary cutters are generated by rolling.
import assert from 'node:assert/strict';
import {legoParts} from '../../src/mechanics/graph/lego-parts.ts';
import {legoSpec,matesFor,spurSpec} from '../../src/mechanics/kinematics/catalog.ts';
import {route} from '../../src/mechanics/kinematics/search/route.ts';
import {solve} from '../../src/mechanics/kinematics/solver.ts';
import {compatible} from '../../src/mechanics/kinematics/profiles.ts';
import {involuteOutline} from '../../src/mechanics/kinematics/generate/involute.ts';
import {generateMate,countTeeth,toothThickness,polarRadius,extrudeStar} from '../../src/mechanics/kinematics/generate/hull.ts';
import {watertight,volume} from '../../src/mechanics/kinematics/generate/mesh.ts';
import {identity,axisAngle} from '../../src/mechanics/kinematics/math.ts';

const close=(a,b,tol,what)=>assert.ok(Math.abs(a-b)<=tol,`${what}: ${a} vs ${b}`);
const lego24=legoSpec(legoParts.find(p=>p.search&&p.teeth===24&&p.mount==='cross'),'spur');

// Mates follow from the basic rack: every tooth count, no partner list.
{const mates=matesFor(lego24,[8,80]);assert.equal(mates.length,73);assert.ok(mates.every(c=>c.b.surfaces[0].profile.module===1));
 assert.ok(compatible(lego24.surfaces[0].profile,mates[0].b.surfaces[0].profile).ok);
 assert.equal(matesFor(spurSpec(30,2),[10,12]).map(c=>c.b.key.split(':')[1]).join(),'2,2,2','module carried from the given part');}

// Search: LEGO 24 on the input, output 30 mm away and parallel, ratio 1.5 → printed z36 m1 (not a catalog size).
{const input={kind:'frame',local:identity(),target:{position:[10,-20,5],rotation:axisAngle([1,1,0],30)},constraint:'frame'};
 const target={...input.target,position:[0,0,0]},offset=[30,0,0];
 // Output 30 mm along the input frame's x axis.
 const q=input.target.rotation,rot=v=>{const [x,y,z,w]=q,[vx,vy,vz]=v,tx=2*(y*vz-z*vy),ty=2*(z*vx-x*vz),tz=2*(x*vy-y*vx);return [vx+w*tx+y*tz-z*ty,vy+w*ty+z*tx-x*tz,vz+w*tz+x*ty-y*tx];};
 const d=rot(offset);target.position=[input.target.position[0]+d[0],input.target.position[1]+d[1],input.target.position[2]+d[2]];
 const output={kind:'frame',local:identity(),target,constraint:'axis'};
 const r=await route({input,output},{target:1.5,tolerance:1,maxStages:1,budget:20000,rules:['generated-mate'],input:lego24,mateTeeth:[8,80],yield:false});
 assert.ok(r.solutions.length>=1,'mate found: '+JSON.stringify(r.rejections));
 const s=r.solutions[0],stage=s.chain.stages[0];
 assert.equal(stage.choice.a.key,lego24.key,'driver is the given LEGO part');
 assert.equal(stage.choice.b.key.split(':').slice(0,3).join(':'),'spur:1:36','printed mate z36 m1');
 assert.equal(s.mechanism.elements.filter(e=>e.source.kind==='printed').length,1,'exactly one printed part');
 const m=structuredClone(s.mechanism);m.range={from:0,to:180,samples:5};const k=await solve(m,{yield:false});
 assert.equal(k.checks.find(c=>c.id==='closure').state,'pass',k.checks.find(c=>c.id==='closure').message);
 close(1/Math.abs(k.transfer.constant),1.5,1e-9,'transfer');}

// Rolling generator reproduces a conjugate involute: z24 cutter → z36 mate.
{const m=1,bl=.15,cutter=involuteOutline({module:m,teeth:24,backlash:bl,samples:24});
 const mate=generateMate({cutter,cutterRadius:12,mateRadius:18,addendum:m,dedendum:1.25*m});
 assert.equal(countTeeth(mate),36,'36 teeth');
 const reference=involuteOutline({module:m,teeth:36,backlash:-bl,samples:40}),refRadius=Array.from({length:mate.radius.length},(_,k)=>polarRadius(reference,mate.theta[k]));
 close(toothThickness(mate.radius,18),toothThickness(refRadius,18),.04,'thickness at pitch circle');
 close(toothThickness(mate.radius,17.5),toothThickness(refRadius,17.5),.05,'thickness below pitch');
 close(toothThickness(mate.radius,18.5),toothThickness(refRadius,18.5),.05,'thickness above pitch');}

// Arbitrary cutter: twelve rounded lobes on a 24 mm pitch circle, mate at 1:2 has 24 lobes, no interference, closed solid.
{const ra=12,lobes=12,amp=.8,cutter=Array.from({length:720},(_,k)=>{const t=2*Math.PI*k/720,r=ra+amp*Math.cos(lobes*t);return [r*Math.cos(t),r*Math.sin(t)];});
 const mate=generateMate({cutter,cutterRadius:ra,mateRadius:2*ra,addendum:1.2,dedendum:1.4});
 assert.equal(countTeeth(mate,2*ra),24,'24 lobes');
 let worst=0;const d=3*ra;
 for(let k=0;k<400;k++){const arc=k*.0731,psiB=arc/(2*ra),psiA=-arc/ra,cx=d*Math.cos(-psiB),cy=d*Math.sin(-psiB),rot=psiA-psiB+Math.PI,c=Math.cos(rot),s=Math.sin(rot);
  for(const [x,y] of cutter){const px=cx+x*c-y*s,py=cy+x*s+y*c,r=Math.hypot(px,py);if(r>2*ra+1.2)continue;const t=Math.atan2(py,px),f=(((t%(2*Math.PI))+2*Math.PI)%(2*Math.PI))/(2*Math.PI)*mate.radius.length,i=Math.floor(f)%mate.radius.length,j=(i+1)%mate.radius.length,w=f-Math.floor(f),top=mate.radius[i]*(1-w)+mate.radius[j]*w;worst=Math.max(worst,top-r);}}
 assert.ok(worst<.02,'cutter penetrates generated mate by '+worst.toFixed(4));
 const mesh=extrudeStar(mate.outline,0,8);assert.ok(watertight(mesh),'mate mesh closed');assert.ok(volume(mesh)>0,'outward oriented');}

// A generated profile pairs only with its source and closes in the solver.
{const lego=legoSpec(legoParts.find(p=>p.search&&p.teeth===24&&p.mount==='cross'),'spur');
 const element=(id,spec,body,surface)=>({id,source:spec.source,surfaces:[surface??spec.surfaces[0]],interfaces:spec.interfaces,envelope:spec.envelope,mounts:[{interface:spec.interfaces[0].id,body,pose:identity()}],phase:0});
 const mateSurface={id:'teeth',pitch:{kind:'circle',r:18},profile:{kind:'generated',from:{element:'lego',surface:'teeth'}},z:[-4,4],side:'external'};
 const doc={format:'kinematics-1',parameters:[],patterns:[],bodies:[{id:'ground',frame:identity(),ground:true},{id:'a',frame:identity()},{id:'b',frame:{position:[30,0,0],rotation:[0,0,0,1]}}],
  joints:[{id:'ja',joint:{kind:'revolute'},a:{body:'ground',local:identity()},b:{body:'a',local:identity()}},{id:'jb',joint:{kind:'revolute'},a:{body:'ground',local:{position:[30,0,0],rotation:[0,0,0,1]}},b:{body:'b',local:identity()}}],
  elements:[element('lego',lego,'a'),element('mate',spurSpec(36,1,8),'b',mateSurface)],contacts:[{id:'c',kind:'roll',mode:'fixed-axes',a:{element:'lego',surface:'teeth'},b:{element:'mate',surface:'teeth'},params:{offsetA:0,offsetB:0}}],
  input:{kind:'coordinate',joint:'ja',coordinate:0},output:{kind:'coordinate',joint:'jb',coordinate:0},range:{from:0,to:90,samples:3}};
 const k=await solve(doc,{yield:false});assert.equal(k.checks.find(c=>c.id==='closure').state,'pass');close(k.transfer.constant,-24/36,1e-12,'generated pair ratio');
 const wrong=structuredClone(doc);wrong.elements[1].surfaces[0].profile.from.element='other';await assert.rejects(()=>solve(wrong,{yield:false}),/Quellfläche/);}
console.log('Kinematics mates: LEGO 24 gets a printed z36 mate from the search, rolled mates match involutes and arbitrary cutters, generated profiles pair only with their source.');
